import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

hardsigmoid_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void hardsigmoid_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        // HardSigmoid logic: clamp((val + 3) / 6, 0, 1)
        float tmp = (val + 3.0f) / 6.0f;
        tmp = fminf(fmaxf(tmp, 0.0f), 1.0f);
        output[idx] = tmp;
    }
}

torch::Tensor hardsigmoid_cuda(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);
    const int blockSize = 256;
    const int gridSize = (size + blockSize - 1) / blockSize;
    hardsigmoid_kernel<<<gridSize, blockSize>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
"""

hardsigmoid_cpp_source = r"torch::Tensor hardsigmoid_cuda(torch::Tensor x);"

hardsigmoid_module = load_inline(
    name="hardsigmoid_module",
    cpp_sources=hardsigmoid_cpp_source,
    cuda_sources=hardsigmoid_source,
    functions=["hardsigmoid_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Simple model that performs a HardSigmoid activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.hardsigmoid_impl = hardsigmoid_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.hardsigmoid_impl.hardsigmoid_cuda(x)
